 return {'profile':device+' '+label,'slot':slot,'canvas':[width,width/ratio],'exitCode':r.returncode,'fails':[x for x in text.splitlines() if '[FAIL]' in x],'outOfBounds':[x for x in text.splitlines() if x.startswith('GEOM') and x.endswith('OUT')],'geometry':[x for x in text.splitlines() if x.startswith('GEOM')],'result':[x for x in text.splitlines() if x.startswith('RESULT')],'log':f'matrix_{i}_{width}.log'}
